package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	category := r.URL.Query().Get("cat")
	sortBy := r.URL.Query().Get("sort")

	// Basic input length check
	if len(query) > 200 || len(category) > 50 {
		http.Error(w, "Input too long", http.StatusBadRequest)
		return
	}

	// Build search query - category is validated against allowlist
	validCategories := map[string]bool{"electronics": true, "books": true, "clothing": true, "all": true}
	if !validCategories[category] {
		category = "all"
	}

	// Sort validation - appears safe but sortBy is not in the parameterized portion
	validSorts := []string{"price", "name", "date", "relevance"}
	sortClause := "relevance"
	for _, s := range validSorts {
		if s == sortBy {
			sortClause = sortBy
		}
	}

	// The vulnerability: query parameter is concatenated into SQL
	// The sortClause is validated but query is NOT parameterized
	var sqlStmt string
	if category == "all" {
		sqlStmt = fmt.Sprintf(
			"SELECT id, name, price, description FROM products WHERE name ILIKE '%%%s%%' OR description ILIKE '%%%s%%' ORDER BY %s LIMIT 50",
			query, query, sortClause,
		)
	} else {
		sqlStmt = fmt.Sprintf(
			"SELECT id, name, price, description FROM products WHERE category = '%s' AND (name ILIKE '%%%s%%' OR description ILIKE '%%%s%%') ORDER BY %s LIMIT 50",
			category, query, query, sortClause,
		)
	}

	rows, err := db.Query(sqlStmt)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []string
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		results = append(results, fmt.Sprintf("{\"id\":%d,\"name\":\"%s\",\"price\":%.2f}", id, name, price))
	}

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, "{\"results\":[%s]}", strings.Join(results, ","))
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
